#!/usr/bin/perl
# md2man.pl - turn a KariDNS manual (docs/*.md) into a manual page in man(7) macros (0.7, docs/RELEASING.md "Manual pages").
#
#   perl man/md2man.pl -s SECTION -n NAME [options] docs/FILE.md > man/NAME.SECTION
#
# The Markdown manuals stay the source; the pages in man/ are generated by `make man` and committed, so that building and packaging need no
# tool (tests/run_md2man_test.sh checks that they are fresh and that `mandoc -T lint` finds no error).  Only the Markdown the manuals use is
# understood (CommonMark and the GitHub extensions, as far as these files go):
#
#   # title                 the first one gives NAME when the manual has no NAME section
#   ## heading              .SH          ### heading and deeper: .SS (no font in a heading: the text only)
#   paragraph               .PP          the lines of one paragraph are joined into one line of roff
#   - item, * item, 1. item .IP with a bullet or the number; the lines indented under an item are its blocks (nested lists, code, paragraphs),
#                           the blocks after the first one inside .RS/.RE
#   term + ": text"         a definition list (the option lists): .TP with the term, the text and the indented lines under it as its body
#   ```fenced code```       .nf/.fi, indented by 2 (inside an item as well); tabs expanded to 8 columns
#   | table |               tbl(7) when its widest row fits the width that is left at that indentation of an 80-column terminal; otherwise
#                           a tagged list: the first cell is the tag, every other cell a line "Header: text" (two columns: the text alone)
#   > quote, > [!NOTE]      .RS 4/.RE; a callout ([!NOTE], [!WARNING], ...) starts with "Note:", "Warning:", ... in bold
#   ---                     dropped (a rule between sections); so is a fenced block right after the title that only repeats the page header
#   `code`, **bold**        bold          *italic*: italic          [text](target): the text, and " <target>" for a URL other than the text
#   \X (X punctuation)      X             <https://...>: the URL
#
# Everything roff would interpret is escaped: a backslash is \e, a line never starts with "." or "'" (\& before it), a hyphen in code, in an
# option (-x, --name) and at the start of a word is \- (so that a copied option is ASCII), every character outside ASCII is \[uXXXX], a double
# quote in a macro argument is \(dq, and a table cell starts with \& (a cell "_" or "=" would be a rule in tbl).
#
# Options:
#   -s SECTION         the section (1, 5, 8): .TH
#   -n NAME            the name of the page (.TH and the NAME line)
#   -d DATE            the date of .TH (the Makefile passes the contents of man/DATE, so that a page does not change with the day)
#   --name-desc TEXT   the text of the NAME line (instead of the NAME section of the manual or its title)
#   --synopsis LINE    a SYNOPSIS line, repeatable, when the manual has no SYNOPSIS section
#   --only REGEX       keep only the ## sections whose heading matches (NAME and SYNOPSIS are always made)
#   --omit REGEX       drop the ## sections whose heading matches ...
#   --omit-note H=TEXT ... and put a section H with the paragraph TEXT where the first of them was
#   --see-also TEXT    a paragraph at the start of SEE ALSO (the section is made when the manual has none)
#   --report           print to stderr the tables that became tagged lists
use strict;
use warnings;
use Getopt::Long qw(:config no_ignore_case bundling);

my ($SEC, $NAME, $DATE, $NAMEDESC, $ONLY, $OMIT, $OMITNOTE, $SEEALSO, $REPORT) = ('', '', '', undef, undef, undef, undef, undef, 0);
my @SYNOPSIS;
my $USAGE = "usage: md2man.pl -s SECTION -n NAME [-d DATE] [--name-desc TEXT] [--synopsis LINE]... [--only RE] [--omit RE [--omit-note H=TEXT]] [--see-also TEXT] [--report] FILE.md\n";
GetOptions('s=s' => \$SEC, 'n=s' => \$NAME, 'd=s' => \$DATE, 'name-desc=s' => \$NAMEDESC, 'synopsis=s' => \@SYNOPSIS, 'only=s' => \$ONLY,
           'omit=s' => \$OMIT, 'omit-note=s' => \$OMITNOTE, 'see-also=s' => \$SEEALSO, 'report' => \$REPORT) or die $USAGE;
@ARGV == 1 or die $USAGE;
$SEC =~ /^[1-9][a-z]*$/ or die "md2man.pl: -s needs a section such as 1, 5 or 8\n";
$NAME =~ /^[A-Za-z0-9][A-Za-z0-9._+-]*$/ or die "md2man.pl: -n needs the name of the page\n";
$DATE =~ /^[A-Za-z0-9 ,.@-]*$/ or die "md2man.pl: -d: a date such as 2026-11-13\n";
my $FILE = $ARGV[0];

my $WIDTH = 80;          # the terminal the tables must fit (mandoc -T utf8 -O width=80)
my $BODY = 5;            # the indentation of the text of a section (mandoc -T utf8)
my @TABLES_AS_LISTS;

open my $fh, '<:encoding(UTF-8)', $FILE or die "md2man.pl: $FILE: $!\n";
my @lines = map { s/\r?\n\z//r } <$fh>;
close $fh;

# ---------------------------------------------------------------------------------------------------------------------------------------------
# blocks

sub indent_of { my ($l) = @_; $l =~ /^( *)/; return length $1 }
sub is_blank  { return $_[0] =~ /^\s*$/ }
sub detab     { my ($l) = @_; 1 while $l =~ s/^( *)\t/$1 . (' ' x (8 - length($1) % 8))/e; return $l }   # leading tabs only
sub is_fence  { return $_[0] =~ /^ *(```+|~~~+)/ }
sub is_table_delim { return $_[0] =~ /^ *\|? *:?-+:? *(\| *:?-+:? *)*\|? *$/ && $_[0] =~ /-/ && $_[0] =~ /\|/ }

# a line that starts a block of its own (it ends a paragraph)
sub starts_block {
    my ($l) = @_;
    return 1 if is_fence($l) || $l =~ /^ {0,3}#{1,6}( |$)/ || $l =~ /^ *>/ || $l =~ /^ *\|/ || $l =~ /^ {0,3}(-{3,}|\*{3,}|_{3,}) *$/;
    return 1 if $l =~ /^ *([-*+]|\d{1,9}[.)]) +\S/;
    return 0;
}

sub parse_blocks {
    my @L = map { detab($_) } @_;
    my @b;
    my $i = 0;
    while ($i < @L) {
        my $l = $L[$i];
        if (is_blank($l)) { $i++; next }
        if ($l =~ /^( *)(```+|~~~+)/) {                                                  # fenced code
            my ($ind, $f) = (length $1, $2);
            my @c;
            $i++;
            while ($i < @L && $L[$i] !~ /^ *\Q$f\E\s*$/) {
                my $c = $L[$i++];
                my $n = indent_of($c);
                push @c, substr($c, $n < $ind ? $n : $ind);
            }
            $i++;
            push @b, { t => 'code', lines => \@c };
            next;
        }
        if ($l =~ /^ {0,3}(#{1,6}) +(.*?)(?: +#+)? *$/) {                              # heading
            push @b, { t => 'h', level => length $1, text => $2 };
            $i++;
            next;
        }
        if ($l =~ /^ {0,3}(-{3,}|\*{3,}|_{3,}) *$/) { $i++; push @b, { t => 'hr' }; next }
        if ($l =~ /^ *\|/ && $i + 1 < @L && is_table_delim($L[$i + 1])) {                 # table
            my @rows;
            push @rows, $L[$i++] while $i < @L && $L[$i] =~ /^ *\|/;
            push @b, parse_table(@rows);
            next;
        }
        if ($l =~ /^ *>/) {                                                              # quote or callout
            my @q;
            while ($i < @L && $L[$i] =~ /^ *> ?(.*)$/) { push @q, $1; $i++ }
            my $kind = '';
            if (@q && $q[0] =~ /^\[!([A-Za-z]+)\]\s*(.*)$/) { $kind = ucfirst lc $1; $q[0] = $2 }
            push @b, { t => 'quote', kind => $kind, blocks => [parse_blocks(@q)] };
            next;
        }
        if ($l =~ /^( *)([-*+]|\d{1,9}[.)])( +|$)/) {                                     # list
            my $r = parse_list(\@L, $i);
            $i = $r->{next};
            push @b, $r->{block};
            next;
        }
        if ($i + 1 < @L && $l !~ /^ / && $L[$i + 1] =~ /^: /) {                           # definition list
            my $r = parse_deflist(\@L, $i);
            $i = $r->{next};
            push @b, $r->{block};
            next;
        }
        my @p = ($l);                                                                    # paragraph
        $i++;
        while ($i < @L && !is_blank($L[$i]) && !starts_block($L[$i]) && !($i + 1 < @L && $L[$i] !~ /^ / && $L[$i + 1] =~ /^: /)) { push @p, $L[$i++] }
        push @b, { t => 'p', text => join(' ', map { s/^\s+|\s+$//gr } @p) };
    }
    return @b;
}

# the lines of one item: the first line's text, then the lines under it, without the indentation of the item's text
sub item_lines {
    my ($L, $i, $first, $ccol, $cmin, $is_next) = @_;
    my @c = ($first);
    my $j = $i + 1;
    while ($j < @$L) {
        my $l = $L->[$j];
        if (is_blank($l)) {
            my $k = $j;
            $k++ while $k < @$L && is_blank($L->[$k]);
            last if $k >= @$L || indent_of($L->[$k]) < $cmin;
            push @c, ('') x ($k - $j);
            $j = $k;
            next;
        }
        last if $is_next->($l);
        my $n = indent_of($l);
        if ($n >= $cmin) { push @c, substr($l, $n < $ccol ? $n : $ccol); $j++; next }
        last if is_blank($c[-1]) || starts_block($l) || $l =~ /^: / || ($j + 1 < @$L && $L->[$j + 1] =~ /^: /);
        push @c, $l =~ s/^ +//r;                                                         # a lazy continuation of the paragraph
        $j++;
    }
    pop @c while @c && is_blank($c[-1]);
    return ($j, @c);
}

sub parse_list {
    my ($L, $i) = @_;
    $L->[$i] =~ /^( *)([-*+]|\d{1,9}[.)])/;
    my $ind = length $1;
    my $ordered = $2 =~ /\d/ ? 1 : 0;
    my $same = sub {
        my ($l) = @_;
        return 0 unless $l =~ /^( *)([-*+]|\d{1,9}[.)])( +|$)/;
        return length($1) == $ind && (($2 =~ /\d/ ? 1 : 0) == $ordered);
    };
    my @items;
    while ($i < @$L && $same->($L->[$i])) {
        $L->[$i] =~ /^( *)([-*+]|\d{1,9}[.)])( *)(.*)$/;
        my ($mk, $sp, $text) = ($2, $3, $4);
        $sp = ' ' if length $sp > 4 || $text eq '';
        my $ccol = $ind + length($mk) + length($sp);
        my $cmin = $ind + 2 < $ccol ? $ind + 2 : $ccol;
        my ($j, @c) = item_lines($L, $i, $text, $ccol, $cmin, $same);
        push @items, { marker => $mk, blocks => [parse_blocks(@c)] };
        $i = $j;
        my $k = $i;
        $k++ while $k < @$L && is_blank($L->[$k]);
        last unless $k < @$L && $same->($L->[$k]);
        $i = $k;
    }
    return { next => $i, block => { t => $ordered ? 'ol' : 'ul', items => \@items } };
}

sub parse_deflist {
    my ($L, $i) = @_;
    my @items;
    my $is_term = sub { my ($j) = @_; return $j + 1 < @$L && !is_blank($L->[$j]) && $L->[$j] !~ /^ / && $L->[$j + 1] =~ /^: / };
    while ($i < @$L && $is_term->($i)) {
        my $term = $L->[$i] =~ s/^\s+|\s+$//gr;
        $i++;
        my @c;
        while ($i < @$L && $L->[$i] =~ /^: (.*)$/) {                                      # one ": " line or more: paragraphs of the same item
            push @c, '' if @c;
            my $first = $1;
            my ($j, @d) = item_lines($L, $i, $first, 2, 2, sub { $_[0] =~ /^: / });
            push @c, @d;
            $i = $j;
            my $k = $i;
            $k++ while $k < @$L && is_blank($L->[$k]);
            last unless $k < @$L && $L->[$k] =~ /^: /;
            $i = $k;
        }
        push @items, { term => $term, blocks => [parse_blocks(@c)] };
        my $k = $i;
        $k++ while $k < @$L && is_blank($L->[$k]);
        last unless $k < @$L && $is_term->($k);
        $i = $k;
    }
    return { next => $i, block => { t => 'dl', items => \@items } };
}

sub split_row {
    my ($r) = @_;
    $r =~ s/^\s*\|//;
    $r =~ s/(?<!\\)\|\s*$//;
    my @c = split /(?<!\\)\|/, $r, -1;
    return map { my $x = $_; $x =~ s/^\s+|\s+$//g; $x =~ s/\\\|/|/g; $x } @c;
}

sub parse_table {
    my @rows = @_;
    my @head = split_row(shift @rows);
    my @al = map { /^:-+:$/ ? 'c' : /-:$/ ? 'r' : 'l' } map { s/\s//gr } split_row(shift @rows);
    my @body = map { [split_row($_)] } @rows;
    my $n = @head;
    for my $r (@body) { push @$r, '' while @$r < $n; splice @$r, $n }
    push @al, 'l' while @al < $n;
    return { t => 'table', head => \@head, align => [@al[0 .. $n - 1]], rows => \@body };
}

# ---------------------------------------------------------------------------------------------------------------------------------------------
# inline text

sub font_seq { my ($f) = @_; return $f eq 'BI' ? '\f(BI' : "\\f$f" }
sub add_font {
    my ($cur, $f) = @_;
    my %s = map { $_ => 1 } grep { $_ ne 'R' } split //, $cur;
    $s{$f} = 1;
    return $s{B} && $s{I} ? 'BI' : $s{B} ? 'B' : 'I';
}

# text for roff: \ -> \e, outside ASCII -> \[uXXXX], a hyphen in code, or one or two before a letter or digit at the start of a word -> \-
sub esc {
    my ($t, $code) = @_;
    $t =~ s/\\/\\e/g;
    $t =~ s/\t/ /g;                                                                      # (a tab separates the cells of tbl)
    if ($code) {
        $t =~ s/-/\\-/g;
    } else {
        $t =~ s/(?:^|(?<=[\s(\[{"'\/=,|]))(-{1,2})(?=[A-Za-z0-9])/'\\-' x length $1/ge;
    }
    $t =~ s/([^\x00-\x7e])/sprintf('\\[u%04X]', ord $1)/ge;
    return $t;
}

sub plain {                                                                              # the text without the Markdown (headings, widths)
    my ($s) = @_;
    $s =~ s/\[((?:[^\]\\]|\\.)*)\]\([^)\s]*\)/$1/g;
    $s =~ s/<((?:https?|mailto):[^>\s]+)>/$1/g;
    $s =~ s/(`+)(.*?[^`])\1(?!`)/$2/g;
    $s =~ s/\*\*\*(?=\S)(.+?)(?<=[^\s\\])\*\*\*/$1/g;
    $s =~ s/\*\*(?=\S)(.+?)(?<=[^\s\\])\*\*/$1/g;
    $s =~ s/(?<![\w*])\*(?=[^\s*])(.+?)(?<=[^\s*\\])\*(?![\w*])/$1/g;
    $s =~ s/\\([!-\/:-@\[-`{-~])/$1/g;
    return $s;
}

sub inl {
    my ($s, $font) = @_;
    $font //= 'R';
    my $out = '';
    my $prev = '';                                                                       # the last character of the text so far
    while (length $s) {
        if ($s =~ s/^(`+)(.*?[^`])\1(?!`)//s) {                                           # code span
            my $c = $2;
            $c =~ s/^ (.*[^ ].*) $/$1/;
            $out .= font_seq(add_font($font, 'B')) . esc($c, 1) . font_seq($font);
            $prev = substr($c, -1);
            next;
        }
        if ($s =~ s/^\*\*\*(?=\S)(.+?)(?<=[^\s\\])\*\*\*//s) {                                # bold and italic
            my $nf = add_font(add_font($font, 'B'), 'I');
            $out .= font_seq($nf) . inl($1, $nf) . font_seq($font);
            $prev = substr($1, -1);
            next;
        }
        if ($s =~ s/^\*\*(?=\S)(.+?)(?<=[^\s\\])\*\*//s) {                                    # bold
            my $nf = add_font($font, 'B');
            $out .= font_seq($nf) . inl($1, $nf) . font_seq($font);
            $prev = substr($1, -1);
            next;
        }
        if ($prev !~ /\w/ && $s =~ s/^\*(?=[^\s*])(.+?)(?<=[^\s*\\])\*(?![\w*])//s) {     # italic (not inside a word: *.sql stays)
            my $nf = add_font($font, 'I');
            $out .= font_seq($nf) . inl($1, $nf) . font_seq($font);
            $prev = substr($1, -1);
            next;
        }
        if ($s =~ s/^\[((?:[^\]\\]|\\.)*)\]\(([^)\s]*)\)//) {                              # link
            my ($t, $u) = ($1, $2);
            $out .= inl($t, $font);
            $out .= ' <' . esc($u, 1) . '>' if $u =~ m{^(?:https?|mailto):} && plain($t) ne $u;
            $prev = '>';
            next;
        }
        if ($s =~ s/^<((?:https?|mailto):[^>\s]+)>//) { $out .= esc($1, 1); $prev = '>'; next }     # autolink
        if ($s =~ s/^\\([!-\/:-@\[-`{-~])//) { $out .= esc($1, 0); $prev = $1; next }               # backslash escape
        if ($s =~ s/^([^`*\[<\\]+)//) { $out .= esc($1, 0); $prev = substr($1, -1); next }
        $s =~ s/^(.)//s;
        $out .= esc($1, 0);
        $prev = $1;
    }
    return $out;
}

# a line of text: never a request
sub textline {
    my ($t) = @_;
    $t =~ s/^\s+//;
    $t =~ s/\s+$//;
    $t = "\\&$t" if $t =~ /^[.']/;
    return $t;
}

sub macro_arg {                                                                          # the rest of a macro line (.SH, .SS)
    my ($t) = @_;
    $t = esc(plain($t), 0);
    $t =~ s/"/\\(dq/g;
    $t =~ s/^\s+|\s+$//g;
    return $t;
}

# ---------------------------------------------------------------------------------------------------------------------------------------------
# output

my @OUT;
sub emit { push @OUT, @_ }

# render(blocks, indentation in columns, first): first = a paragraph needs no .PP (right after .SH, .SS, .IP, .TP or .RS)
sub render {
    my ($blocks, $ind, $first) = @_;
    for my $b (@$blocks) {
        my $t = $b->{t};
        next if $t eq 'hr';
        if ($t eq 'p') {
            emit('.PP') unless $first;
            emit(wrap(inl($b->{text})));
        } elsif ($t eq 'h') {                                                            # a heading inside an item or a quote: bold text
            emit('.PP') unless $first;
            emit(textline('\fB' . esc(plain($b->{text}), 0) . '\fR'));
        } elsif ($t eq 'code') {
            emit('.PP') unless $first;
            emit('.RS 2', '.nf');
            for my $c (@{ $b->{lines} }) {
                1 while $c =~ s/^([^\t]*)\t/$1 . (' ' x (8 - length($1) % 8))/e;
                $c =~ s/\s+$//;
                my $e = esc($c, 1);
                $e = "\\&$e" if $e =~ /^[.']/ || $e eq '';
                emit($e);
            }
            emit('.fi', '.RE');
        } elsif ($t eq 'ul' || $t eq 'ol') {
            for my $it (@{ $b->{items} }) {
                my ($tag, $w) = $t eq 'ul' ? ('\(bu', 2) : ($it->{marker} =~ s/\)$/./r, 4);
                emit(".IP $tag $w");
                render_item($it->{blocks}, $ind + $w, $w);
            }
        } elsif ($t eq 'dl') {
            for my $it (@{ $b->{items} }) {
                emit('.TP 8', textline(inl($it->{term})));
                render_item($it->{blocks}, $ind + 8, 8);
            }
        } elsif ($t eq 'quote') {
            my @bl = @{ $b->{blocks} };
            if ($b->{kind} ne '') {
                if (@bl && $bl[0]{t} eq 'p') {
                    $bl[0] = { %{ $bl[0] }, text => "**$b->{kind}:** $bl[0]{text}" };
                } else {
                    unshift @bl, { t => 'p', text => "**$b->{kind}:**" };
                }
            }
            emit('.PP') unless $first;
            emit('.RS 4');
            render(\@bl, $ind + 4, 1);
            emit('.RE');
        } elsif ($t eq 'table') {
            render_table($b, $ind, $first);
        }
        $first = 0;
    }
}

# the blocks of an item after its .IP / .TP line: the first paragraph is its text, the other blocks are indented by .RS
sub render_item {
    my ($blocks, $ind, $w) = @_;
    my @bl = @$blocks;
    if (@bl && $bl[0]{t} eq 'p') {
        emit(wrap(inl($bl[0]{text})));
        shift @bl;
    }
    return unless @bl;
    emit(".RS $w");
    render(\@bl, $ind, 0);
    emit('.RE');
}

sub render_table {
    my ($b, $ind, $first) = @_;
    my @head = @{ $b->{head} };
    my $n = @head;
    my @all = (\@head, @{ $b->{rows} });
    my (@w, @mw);                                                                        # the widest cell and the longest word of a column
    for my $r (@all) {
        for my $k (0 .. $n - 1) {
            my $p = plain($r->[$k]);
            $w[$k] = length $p if length $p > ($w[$k] // 0);
            for my $x (split /\s+/, $p) { $mw[$k] = length $x if length $x > ($mw[$k] // 0) }
        }
    }
    $mw[$_] //= 0 for 0 .. $n - 1;
    my $room = $WIDTH - $ind - 1;
    my @c = @w;
    my $sum = sub { my $s = 3 * ($n - 1); $s += $_ for @c; return $s };
    while ($sum->() > $room) {                                                           # narrow the widest column that can be wrapped
        my $k;
        for my $j (0 .. $n - 1) {
            my $min = $mw[$j] > 8 ? $mw[$j] : 8;
            next if $c[$j] <= $min;
            $k = $j if !defined $k || $c[$j] > $c[$k];
        }
        last unless defined $k;
        $c[$k]--;
    }
    my $lines = 0;                                                                       # the most lines a wrapped cell takes (about)
    for my $r (@all) {
        for my $k (0 .. $n - 1) { my $l = int(length(plain($r->[$k])) * 1.15 / $c[$k]) + 1; $lines = $l if $l > $lines }
    }
    if ($sum->() <= $room && $lines <= 8) {
        my @wrap = map { $c[$_] < $w[$_] } 0 .. $n - 1;
        my $cell = sub {
            my ($k, $t) = @_;
            return '\&' . inl($t) unless $wrap[$k] && length plain($t) > $c[$k];
            return join("\n", 'T{', wrap(inl($t)), 'T}');
        };
        my $fmt = sub { my ($bold) = @_; return join(' ', map { $b->{align}[$_] . $bold . ($wrap[$_] ? "w($c[$_])" : '') } 0 .. $n - 1) };
        emit('.PP') unless $first;
        emit('.TS', $fmt->('b'), $fmt->('') . '.');
        for my $r (@all) {
            emit(split /\n/, join("\t", map { $cell->($_, $r->[$_]) } 0 .. $n - 1));
            emit('_') if $r == \@head;
        }
        emit('.TE');
        return;
    }
    # too wide for the terminal: a tagged list (the header names the other cells)
    push @TABLES_AS_LISTS, sprintf('%s: %d columns, %d rows, widest row %d (room %d): %s', $FILE, $n, scalar @{ $b->{rows} }, 3 * ($n - 1) + eval { my $s = 0; $s += $_ for @w; $s }, $room,
                                   join(' | ', map { plain($_) } @head));
    for my $r (@{ $b->{rows} }) {
        emit('.TP 8', textline($r->[0] =~ /\S/ ? inl($r->[0]) : '\(em'));
        my $one = 1;
        for my $k (1 .. $n - 1) {
            next unless $r->[$k] =~ /\S/;
            emit('.br') unless $one;
            my $label = $n > 2 && $head[$k] =~ /\S/ ? '\fI' . esc(plain($head[$k]), 0) . ':\fR ' : '';
            emit(wrap($label . inl($r->[$k])));
            $one = 0;
        }
    }
}

# the lines of a paragraph, at most 80 bytes where a space allows it: never broken after the end of a sentence (roff would add a space there)
# and never so that a line starts with "." or "'"
sub wrap {
    my ($t) = @_;
    $t = textline($t);
    my @out;
    while (length $t > 80) {
        my $cut;
        for (my $p = rindex($t, ' ', 80); $p > 0; $p = rindex($t, ' ', $p - 1)) {
            my $before = substr($t, 0, $p);
            next if $before =~ /[.!?][)"'\]*]*$/ || $before =~ / $/;
            next if substr($t, $p + 1) =~ /^[.']/;
            $cut = $p;
            last;
        }
        if (!defined $cut) {                                                             # a long word: the first space after it that may be used
            for (my $p = index($t, ' ', 81); $p > 0; $p = index($t, ' ', $p + 1)) {
                my $before = substr($t, 0, $p);
                next if $before =~ /[.!?][)"'\]*]*$/ || $before =~ / $/ || substr($t, $p + 1) =~ /^[.' ]/;
                $cut = $p;
                last;
            }
        }
        last unless defined $cut;
        push @out, substr($t, 0, $cut);
        $t = substr($t, $cut + 1);
    }
    push @out, $t;
    return @out;
}

# ---------------------------------------------------------------------------------------------------------------------------------------------
# the page

my @blocks = parse_blocks(@lines);

# the title, and the fenced block that only repeats the page header (KARICTL(8)  KariDNS Manual  KARICTL(8))
my $title = '';
if (@blocks && $blocks[0]{t} eq 'h' && $blocks[0]{level} == 1) {
    $title = plain((shift @blocks)->{text});
    shift @blocks if @blocks && $blocks[0]{t} eq 'code' && @{ $blocks[0]{lines} } == 1 && $blocks[0]{lines}[0] =~ /^\s*\S+\(\d\w*\)\s.*\S+\(\d\w*\)\s*$/;
}
# ... and the one at the end that repeats the page footer (KariDNS  September 2026  KARICTL(8))
pop @blocks if @blocks && $blocks[-1]{t} eq 'code' && @{ $blocks[-1]{lines} } == 1 && $blocks[-1]{lines}[0] =~ /^\s*\S+\s{2,}\S.*\s{2,}\S+\(\d\w*\)\s*$/;

# grouped by ## heading (a # heading after the title is a section as well)
my (@pre, @sections);
for my $b (@blocks) {
    next if $b->{t} eq 'hr';
    if ($b->{t} eq 'h' && $b->{level} <= 2) {
        push @sections, { head => plain($b->{text}), blocks => [] };
    } elsif (@sections) {
        push @{ $sections[-1]{blocks} }, $b;
    } else {
        push @pre, $b;
    }
}
my %sec;
$sec{ uc $_->{head} } //= $_ for @sections;

# NAME: the name, " \- " and the text after the dash of the NAME section (or of the title)
my $namedesc;
if (defined $NAMEDESC) {
    $namedesc = inl($NAMEDESC);
} elsif ($sec{NAME} && @{ $sec{NAME}{blocks} } && $sec{NAME}{blocks}[0]{t} eq 'p') {
    my $p = $sec{NAME}{blocks}[0]{text};
    $p =~ s/^\*\*[^*]+\*\*\s*//;
    $p =~ s/^(?:\x{2014}|\x{2013}|--?)\s*//;
    $namedesc = inl($p);
} else {
    my $d = $title;
    $d =~ s/^.*?(?:\x{2014}|\x{2013}| - )\s*//;
    $namedesc = esc($d, 0);
}

emit(sprintf('.TH %s %s "%s" "KariDNS" "KariDNS Manual"', esc(uc $NAME, 1), $SEC, $DATE));
emit('.\" Generated from ' . $FILE . ' by man/md2man.pl (make man): edit the Markdown manual, not this page.');
emit('.SH NAME', wrap(esc($NAME, 1) . ' \- ' . $namedesc));

if ($sec{SYNOPSIS}) {
    emit('.SH SYNOPSIS');
    render($sec{SYNOPSIS}{blocks}, $BODY, 1);
} elsif (@SYNOPSIS) {
    emit('.SH SYNOPSIS', '.nf');
    emit(map { my $e = esc($_, 1); $e =~ /^[.']/ ? "\\&$e" : $e } @SYNOPSIS);
    emit('.fi');
}
if (@pre) {
    emit('.SH DESCRIPTION');
    render(\@pre, $BODY, 1);
}

my $noted = 0;
my $saw_see_also = 0;
for my $s (@sections) {
    my $h = uc $s->{head};
    next if $h eq 'NAME' || $h eq 'SYNOPSIS';
    my $omit = defined $OMIT && $s->{head} =~ /$OMIT/;
    if ($omit || (defined $ONLY && $s->{head} !~ /$ONLY/)) {
        if ($omit && defined $OMITNOTE && !$noted) {
            my ($nh, $nt) = split /=/, $OMITNOTE, 2;
            emit('.SH ' . macro_arg($nh), wrap(inl($nt)));
            $noted = 1;
        }
        next;
    }
    emit('.SH ' . macro_arg($s->{head}));
    my @bl = @{ $s->{blocks} };
    if ($h eq 'SEE ALSO') {
        $saw_see_also = 1;
        unshift @bl, { t => 'p', text => $SEEALSO } if defined $SEEALSO;
    }
    my $first = 1;                                                                       # the ### headings of the section: .SS
    my @run;
    for my $b (@bl, { t => 'end' }) {
        if ($b->{t} eq 'h' || $b->{t} eq 'end') {
            if (@run) { render([@run], $BODY, $first); @run = () }
            last if $b->{t} eq 'end';
            emit('.SS ' . macro_arg($b->{text}));
            $first = 1;
        } else {
            push @run, $b;
            next;
        }
    }
}
emit('.SH SEE ALSO', wrap(inl($SEEALSO))) if !$saw_see_also && defined $SEEALSO;

binmode STDOUT, ':raw';
for (@OUT) {
    die "md2man.pl: $FILE: a character outside ASCII is left in: $_\n" if /[^\x00-\x7e]/;
    print "$_\n";
}
if ($REPORT) { print STDERR "tagged list: $_\n" for @TABLES_AS_LISTS }
exit 0;
